arguments.commandLine:
@"'flappy-bird.html' | New-Item -ItemType File -Value @"
<html>
<head>
    <title>Flappy Bird</title>
    <style>
        body { margin: 0; padding: 0; overflow: hidden; background-color: #70c5ce; }
        canvas { display: block; margin: auto; }
    </style>
</head>
<body>
<canvas id="gameCanvas" width=400 height=600></canvas>
<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

let frame = 0;
const DEGREE = Math.PI / 180;

// Game state
let gameState = { current: 0, getReady: 0, gameover: 0 };

// Bird object
const bird = {
    x: 50, y: 150, width: 34, height: 26, radius: 12,
    velocity: 0, gravity: 0.25, jump: 4.6, rotation: 0,
    draw: function() {
        ctx.save();
        ctx.translate(this.x, this.y);
        ctx.rotate(this.rotation * DEGREE);

        // Bird body
        ctx.fillStyle = '#FFD700';
        ctx.beginPath();
        ctx.ellipse(0, 0, this.radius + 5, this.radius, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 2;
        ctx.stroke();

        // Eye
        ctx.fillStyle = '#FFF';
        ctx.beginPath();
        ctx.arc(6, -6, 4, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(8, -6, 1, 0, Math.PI * 2);
        ctx.fill();

        // Beak
        ctx.fillStyle = '#FFA500';
        ctx.beginPath();
        ctx.moveTo(8, 2);
        ctx.lineTo(16, 6);
        ctx.lineTo(8, 10);
        ctx.fill();
        ctx.stroke();

        // Wing
        ctx.fillStyle = '#FFF';
        ctx.beginPath();
        ctx.ellipse(-4, 4, 6, 4, -0.2, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();

        ctx.restore();
    },
    update: function() {
        // Only animate when not in game over state
        if (gameState.current !== gameState.gameover) {
            this.y += this.velocity;
            this.velocity += this.gravity;

            // Floor collision
            if (this.y + this.height/2 >= canvas.height - fg.height) {
                this.y = canvas.height - fg.height - this.height/2;
                gameState.current = gameState.gameover;
            }

            // Ceiling collision
            if (this.y - this.height/2 <= 0) {
                this.y = this.height/2;
                this.velocity = 0;
            }
        } else if (gameState.current === gameState.getReady) {
            // Bobbing effect in get ready state
            this.y = 150 + Math.sin(Date.now() / 200) * 5;
        }
    },
    flap: function() {
        this.velocity = -this.jump;
    },
    rotate: function() {
        // Calculate rotation based on velocity
        if (this.velocity < 0) {
            this.rotation = -25;
        } else if (this.velocity > 0) {
            this.rotation = Math.min(90, this.velocity * 3);
        } else {
            this.rotation = 0;
        }
    }
};

// Foreground platform
const fg = {
    x: 0, y: 0, width: canvas.width, height: 112,
    draw: function() {
        ctx.fillStyle = '#ded895';
        ctx.fillRect(this.x, this.y, this.width, this.height);

        // Grass pattern
        ctx.fillStyle = '#73bf2e';
        for (let i = 0; i < this.width + 20; i += 20) {
            ctx.beginPath();
            ctx.moveTo(this.x + i, this.y + 10);
            ctx.lineTo(this.x + i + 5, this.y + 5);
            ctx.lineTo(this.x + i + 10, this.y + 10);
            ctx.fill();
        }

        ctx.strokeStyle = '#000';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, this.y);
        ctx.lineTo(canvas.width, this.y);
        ctx.stroke();
    }
};

// Background
const bg = {
    x: 0, y: 0, width: canvas.width, height: canvas.height,
    draw: function() {
        // Sky
        const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height - fg.height);
        gradient.addColorStop(0, '#70c5ce');
        gradient.addColorStop(1, '#ffffff');
        ctx.fillStyle = gradient;
        ctx.fillRect(this.x, this.y, this.width, this.height);

        // Clouds (simple white circles)
        ctx.fillStyle = 'rgba(255, 255, 255, 0.6)';
        for (let i = 0; i < 5; i++) {
            let cloudX = (i * 150 + Date.now() / 50 - frame * 50) % (canvas.width + 200) - 100;
            let radius = 20 + i * 5;
            ctx.beginPath();
            ctx.arc(cloudX, 80 + i * 30, radius, 0, Math.PI * 2);
            ctx.fill();
        }

        // City skyline silhouette
        ctx.fillStyle = '#a3e4cb';
        let buildings = [
            {x: -50, h: 100}, {x: 80, h: 150}, {x: 220, h: 80},
            {x: 300, h: 180}, {x: 420, h: 120}, {x: 520, h: 90},
            {x: 600, h: 200}, {x: 750, h: 140}
        ];
        for (let b of buildings) {
            ctx.fillRect(b.x, canvas.height - fg.height - b.h, b.width || 40, b.h);
            // Windows
            ctx.fillStyle = '#fff';
            if (Math.random() > 0.5) {
                ctx.fillRect(b.x + 10, canvas.height - fg.height - b.h + 10, 8, 8);
                ctx.fillRect(b.x + 30, canvas.height - fg.height - b.h + 40, 6, 6);
            }
            ctx.fillStyle = '#a3e4cb';
        }
    }
};

// Pipes
const pipes = {
    position: [],
    width: 52, height: 400, gap: 100, dx: 2,
    draw: function() {
        for (let i = 0; i < this.position.length; i++) {
            let p = this.position[i];
            let topY = p.y;
            let bottomY = p.y + this.height + this.gap;

            // Top pipe
            ctx.fillStyle = '#2d5a27';
            ctx.fillRect(p.x, topY, this.width, this.height);
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 2;
            ctx.strokeRect(p.x, topY, this.width, this.height);

            // Pipe cap (top)
            ctx.fillStyle = '#2d5a27';
            ctx.fillRect(p.x - 2, topY + this.height - 20, this.width + 4, 20);
            ctx.strokeRect(p.x - 2, topY + this.height - 20, this.width + 4, 20);

            // Bottom pipe
            ctx.fillStyle = '#2d5a27';
            ctx.fillRect(p.x, bottomY, this.width, this.height);
            ctx.strokeRect(p.x, bottomY, this.width, this.height);

            // Pipe cap (bottom)
            ctx.fillStyle = '#2d5a27';
            ctx.fillRect(p.x - 2, bottomY, this.width + 4, 20);
            ctx.strokeRect(p.x - 2, bottomY, this.width + 4, 20);
        }
    },
    update: function() {
        // Add new pipe every 150 frames
        if (frame % 150 === 0) {
            this.position.push({
                x: canvas.width,
                y: -150 * (Math.random() + 1)
            });
        }

        for (let i = 0; i < this.position.length; i++) {
            let p = this.position[i];
            p.x -= this.dx;

            // Remove pipes that have gone off screen
            if (p.x + this.width <= 0) {
                this.position.shift();
                score.value += 1;
                score.best = Math.max(score.value, score.best);
                localStorage.setItem('flappy_best', score.best);
            }
        }
    },
    reset: function() {
        this.position = [];
    }
};

// Score
const score = {
    best: localStorage.getItem('flappy_best') || 0,
    value: 0,
    draw: function() {
        ctx.fillStyle = '#FFF';
        ctx.strokeStyle = '#000';

        if (gameState.current == gameState.gameover) {
            // Game over screen
            ctx.font = '35px Arial';
            ctx.fillText('Game Over', 120, 150);
            ctx.strokeText('Game Over', 120, 150);

            ctx.font = '20px Arial';
            ctx.fillText('Score: ' + this.value, 160, 200);
            ctx.strokeText('Score: ' + this.value, 160, 200);
            ctx.fillText('Best: ' + this.best, 175, 230);
            ctx.strokeText('Best: ' + this.best, 175, 230);

            // Restart prompt
            ctx.font = '16px Arial';
            ctx.fillStyle = '#000';
            ctx.fillText('Press Space to restart', 110, 280);
        } else if (gameState.current == gameState.getReady) {
            ctx.font = '35px Arial';
            ctx.fillText('Get Ready!', 135, 200);
            ctx.strokeText('Get Ready!', 135, 200);

            ctx.font = '20px Arial';
            ctx.fillText('Press Space to start', 110, 240);
            ctx.strokeText('Press Space to start', 110, 240);
        } else {
            // Score during game
            ctx.font = '35px Arial';
            ctx.fillText(this.value, canvas.width - 100, 50);
            ctx.strokeText(this.value, canvas.width - 100, 50);

            // High score
            ctx.font = '20px Arial';
            ctx.fillText('Best: ' + this.best, canvas.width - 160, 30);
            ctx.strokeText('Best: ' + this.best, canvas.width - 160, 30);
        }
    },
    reset: function() {
        this.value = 0;
    }
};

// Collision detection
function collision() {
    // Get the pipes at the bird's x position
    for (let i = 0; i < pipes.position.length; i++) {
        let p = pipes.position[i];
        let topPipeY = p.y;
        let bottomPipeY = p.y + pipes.height + pipes.gap;

        // Check collision with top pipe
        if (bird.x + bird.radius > p.x && 
            bird.x - bird.radius < p.x + pipes.width &&
            bird.y - bird.radius < topPipeY + pipes.height) {
            return true;
        }

        // Check collision with bottom pipe
        if (bird.x + bird.radius > p.x && 
            bird.x - bird.radius < p.x + pipes.width &&
            bird.y + bird.radius > bottomPipeY) {
            return true;
        }
    }
    return false;
}

// Draw background elements
function drawBackground() {
    bg.draw();
}

// Main loop
function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw layers from back to front
    drawBackground();
    pipes.draw();
    fg.draw();
    bird.draw();
    score.draw();
}

function update() {
    bird.update();
    fg.x = (frame % 20) * (-1); // Moving ground effect

    if (gameState.current == gameState.gameover) {
        return;
    }

    pipes.update();
}

function manage() {
    // Update frames
    frame++;

    // Draw and update
    draw();

    // If game over, show score screen
    if (gameState.current == gameState.gameover) {
        gameState.current = gameState.gameover;
    }
}

// Event listeners
canvas.addEventListener('click', function() {
    switch (gameState.current) {
        case gameState.getReady:
            gameState.current = gameState.playing;
            bird.flap();
            break;
        case gameState.playing:
            bird.flap();
            break;
        case gameState.gameover:
            pipes.reset();
            score.reset();
            bird.y = 150;
            bird.velocity = 0;
            bird.rotation = 0;
            gameState.current = gameState.getReady;
            frame = 0;
            break;
    }
});

document.addEventListener('keydown', function(e) {
    if (e.code === 'Space') {
        e.preventDefault(); // Prevent scrolling

        switch (gameState.current) {
            case gameState.getReady:
                gameState.current = gameState.playing;
                bird.flap();
                break;
            case gameState.playing:
                bird.flap();
                break;
            case gameState.gameover:
                pipes.reset();
                score.reset();
                bird.y = 150;
                bird.velocity = 0;
                bird.rotation = 0;
                gameState.current = gameState.getReady;
                frame = 0;
                break;
        }
    }
});

// Animation loop
function loop() {
    update();
    manage();
    requestAnimationFrame(loop);
}

// Start the game
loop();
</script>
</body>
</html>@" | Out-File -FilePath $tempFile
$tempFile"
